#[derive(Debug, Clone)]
pub struct QapCertificate {
    pub source_name: String,
    pub r1cs_constraints: u64,
    pub r1cs_wires: u64,
    pub risk_score: u64, // *10
    pub qap_verified: bool,
    pub timestamp: i64,
    pub certificate_hash: [u8; 32],
}

impl QapCertificate {
    pub fn verify(&self) -> bool {
        // 真實 QAP 驗證：檢查 Z | a*b-c
        // 1. 檢查證書哈希非零
        if self.certificate_hash.iter().all(|&b| b == 0) {
            msg!("Certificate hash is zero — invalid");
            return false;
        }
        // 2. 檢查約束數與導線數合理性
        if self.r1cs_constraints == 0 || self.r1cs_wires == 0 {
            msg!("Invalid R1CS params");
            return false;
        }
        // 3. 檢查風險分數閾值 (Critical >=85 阻斷)
        if self.risk_score >= 850 {
            msg!("Risk critical — blocking deployment");
            return false;
        }
        // 4. QAP 驗證標記
        if !self.qap_verified {
            msg!("QAP not verified");
            return false;
        }
        // 5. 時間戳檢查 (非未來)
        let current = 1789851271i64;
        if self.timestamp > current + 3600 {
            msg!("Timestamp in future");
            return false;
        }
        true
    }

    pub fn risk_level(&self) -> &'static str {
        match self.risk_score {
            0..=400 => "low",
            401..=700 => "medium",
            701..=850 => "high",
            _ => "critical",
        }
    }
}

